@staticmethod
def from_major_units(major: float, currency: str) -> "Money":
    # 简化处理：所有支持币种均按 100 倍换算（JPY 实际为 1，demo 暂统一）
    return Money.of(round(major * 100), currency)

VALID_ROLES = ("buyer", "agent")


def _now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


@dataclass(frozen=True)
class ConversationTurn:
    """一轮完整问答。turn_index 由存储层按会话自增，写入时可留空。"""

    session_id: str
    buyer_id: str
    role: str  # buyer / agent
    content: str
    model: str = ""
    latency_ms: int = 0
    created_at: str = field(default_factory=_now_iso)

    def __post_init__(self) -> None:
        if not self.session_id:
            raise ValueError("ConversationTurn.session_id required")

def __post_init__(self) -> None:
    if self.kind not in VALID_KINDS:
        raise ValueError(f"BuyerPreference.kind 必须是 {VALID_KINDS}：{self.kind}")
    if not self.statement or not self.statement.strip():
        raise ValueError("BuyerPreference.statement required")
    if not self.created_at:
        object.__setattr__(self, "created_at", datetime.now(timezone.utc).isoformat())

if not self._enabled or not is_cacheable_query(query):
    return None
entries = await self._load_entries(buyer_id, scope)
if not entries:
    return None

if isinstance(cached, list) and cached:
    self.hits += 1
    results.append(cached)

entries.append({"query": _normalize(query), "reply": reply, "vector": vector})
try:
    await self._cache.set_json(key, entries[:_BUCKET_LIMIT], _TTL_SECONDS)

try:
    return json.loads(raw)
except ValueError:
    # 脏值当未命中，顺手删掉
    await self.delete(key)
    return None

if self._client is None:
    return True
try:
    return bool(await self._client.set(key, value, ex=ttl_seconds, nx=True))
except Exception as err:  # noqa: BLE001
    logger.warning("Redis SETNX 失败，放行本次请求：%s（%s）", key, err)
    return True
